package cloud
import("net/http/httptest";"strings";"testing")
func editorTestPolicy()map[string]any{return map[string]any{"provider":"Provider","targetType":"SERVICE_DEF","target":"temperature","cloud":"LOCAL","defaultPolicy":map[string]any{"policyType":"WHITELIST","policyList":[]any{"Consumer"}},"scopedPolicies":map[string]any{"read":map[string]any{"policyType":"ALL","policyList":[]any{}}}}}
func TestPolicyEditorLocalValidation(t *testing.T){systems:=[]any{map[string]any{"name":"Provider"}};services:=[]any{map[string]any{"provider":map[string]any{"name":"Provider"},"serviceDefinition":map[string]any{"name":"temperature"}}};if _,e:=validateEditorPolicy(editorTestPolicy(),systems,services);e!=nil{t.Fatal(e)};for _,change:=range []func(map[string]any){func(p map[string]any){p["cloud"]="Other|Company"},func(p map[string]any){p["level"]="PROVIDER"},func(p map[string]any){p["provider"]="Unknown"},func(p map[string]any){p["target"]="unknown"},func(p map[string]any){p["scopedPolicies"]=map[string]any{"bad/scope":map[string]any{"policyType":"ALL"}}}}{p:=editorTestPolicy();change(p);if _,e:=validateEditorPolicy(p,systems,services);e==nil{t.Fatal("invalid policy accepted",p)}}}
func TestPolicyEditorConfirmation(t *testing.T){a:=&App{};for _,method:=range []string{"POST","DELETE"}{r:=httptest.NewRequest(method,"/api/orchestration/policies/id",strings.NewReader(`{}`));w:=httptest.NewRecorder();if !a.editorPoliciesHTTP(w,r)||w.Code!=428{t.Fatal(method,w.Code,w.Body.String())}}}
